const SUMMARY = { type: 'object', properties: { area: { type: 'string' }, outFile: { type: 'string' }, validated: { type: 'boolean' }, findings: { type: 'integer' }, dispositions: { type: 'integer' }, severity3: { type: 'integer' }, ownerDecisions: { type: 'string' }, notes: { type: 'string' } }, required: ['area', 'outFile', 'validated', 'findings', 'dispositions', 'notes'] }
const VSUMMARY = { type: 'object', properties: { area: { type: 'string' }, outFile: { type: 'string' }, validated: { type: 'boolean' }, real: { type: 'integer' }, rejected: { type: 'integer' }, fixesChanged: { type: 'integer' }, missed: { type: 'integer' }, notes: { type: 'string' } }, required: ['area', 'outFile', 'validated', 'real', 'rejected', 'missed', 'notes'] }

const IGNORE = 'Ignore these directories entirely: node_modules, dist, .claude, preview-transcript (generated output), artifacts (generated output), deliverables/mockups, deliverables/archive, docs/language-remediation-2026/handoff-2026-11-04 (historical snapshot).'

function auditPrompt(a) {
  const out = `${S}/audit/${a.key}.json`
  const obl = a.obl ? `${S}/obligations/${a.obl}.json` : null
  return `You are a reviewer in the final audit of the Antaeus language remediation. First read the shared brief in full: ${S}/AUDIT_BRIEF.md — it defines the governing principle, the authority documents, how the disputed terms are treated, the owner decisions you must not reopen, how to audit, and the exact output format. Follow it exactly. This stage is READ-ONLY: do not edit the repository.

YOUR AREA: ${a.key} — ${a.title}

Scope — read all of it and trace through shared code as needed. If you find a problem in a file outside your scope, report it anyway with its real file path so it can be routed:
${a.paths.map(p => '- ' + p).join('\n')}

Original rewrite documents for this area (read the exact-replacement rows and the structural requirements that concern it):
${a.docs.map(d => '- ' + d).join('\n')}

Original obligations slice for this area: ${obl ? obl + ' — give EVERY record in its `judge` array a disposition; spot-check `verbatim`; confirm each `watch` record' : 'none (no original records map to this area; `dispositions` may be an empty array unless you find records that belong here)'}
Current rendered walkthrough text for this area (default screens only): ${a.corpus ? `${S}/corpus/${a.corpus}.txt is the enterprise demo book as generated on 2026-11-06 — a later copy pass changed some strings, so where it disagrees with source, SOURCE IS THE TRUTH and the line is stale, not a finding. ${SMB(a.corpus)}${OLDER(a.corpus)}` : 'none — this area is not in the walkthrough; say so in `coverage`'}
Capability map (internal doctrine, embedded in the tester walkthrough): ${a.map || 'n/a'}

Area-specific instructions:
${a.notes}

${IGNORE}

When the complete fix for a finding needs a product decision the owner has not made (it would change which recommendations, data or behavior the product produces, or remove something), put in \`proposed\` the smallest change that makes the screen accurate WITHOUT that decision, then describe the larger option after the words "OWNER DECISION:" at the end of \`proposed\`.
Machine note: other reviewers are working in this checkout at the same time and the machine is small. Do NOT start a browser, a dev server, a build, the whole test suite, or a copy of dist. Prefer reading tests to running them; if you must run one, run a single file with \`npx vitest run <file> --maxWorkers=1\` and never two at once. Small node/grep scripts are fine.

Unverified leads: ${S}/audit-leads/${a.key}.json may exist. If it does, it holds partial notes from an interrupted reviewer that ran on a different model. Treat every entry as an unverified lead: check it yourself at file:line before you include it (re-derive the problem and the fix), and do not assume the notes are complete or correct. They are not a substitute for your own audit of every surface.

SAVE AS YOU GO — this matters. An earlier run of this audit was cut off and every unsaved finding was lost.
- If ${out} already exists when you start, it is a partial result from an interrupted reviewer of this same area. Read it first, keep everything valid in it, and continue with what its \`coverage\` array shows is not yet done. Do not start over.
- Write ${out} as valid JSON (all five arrays present, even if empty) as soon as you have audited your first surface, and rewrite the whole file after each further surface or generator. Add a \`coverage\` row for a surface when you finish it. This machine has been restarting without warning about once an hour, and a restart ends your session: never hold more than FIVE unsaved findings or go more than about ten minutes without saving. When you resume from a partial file, your first save should come within your first few findings, not after you have re-read everything.
- Work in this order so that the most important evidence is saved first: default screens → generators, prompts and fallbacks → data, backend and handoffs → the previous and oldest screen versions → dispositions for the \`judge\` records → gaps.
Be economical: read a file once in full rather than through many small searches, and batch related checks into one command. Do not re-read documents you have already read.

Write your result to: ${out}
Then validate it and fix anything reported: node ${S}/validate-audit.js ${out}${obl ? ' --obligations ' + obl : ''}

Return: the area key, the output file path, whether validation passed, the number of findings and dispositions, how many findings are severity 3, anything that needs an owner decision, and a 5–10 line note (counts by category, the three most important findings, honest limits).`
}

function verifyPrompt(a) {
  const audit = `${S}/audit/${a.key}.json`
  const out = `${S}/audit/${a.key}.verify.json`
  return `You are the independent verifier in the final audit of the Antaeus language remediation. First read the shared brief: ${S}/AUDIT_BRIEF.md (all of it; sections 1–5 govern your judgments), and COPY_STANDARD.md §26 at the repository root (consult other sections as needed). A reviewer audited the area "${a.key} — ${a.title}" and wrote its result to ${audit}. You check that work twice over: is each finding REAL, and is each proposed FIX one the owner would accept. This stage is READ-ONLY: do not edit the repository.

Area scope for context:
${a.paths.map(p => '- ' + p).join('\n')}
Area-specific instructions the reviewer was given:
${a.notes}

For EVERY finding in the audit file, give two verdicts.

(1) \`real\` — try to REFUTE the finding.
- Open the file at the cited line. If the quoted current text is not there, search for it. If it does not exist anywhere in the repository (outside the ignored directories), REJECTED.
- LANG-* and A11Y findings: would a first-time founder or seller really have to translate the text, or be misled, in the place where it appears? REJECT findings that are only a word match (rank / move / room / proof and similar used in an understandable way — see the disputed-terms table), ordinary sales terminology, a clear short label, conversational seller-to-buyer speech, an identifier / comment / test, or text that is already the original approved replacement and has no real comprehension or accuracy problem. Open the cited governing record or rule and confirm it says what the finding claims.
- FUNC, CLAIM and TOOLING findings: verify against the code. Read the implementation and its tests; where practical, reproduce with one vitest file (\`npx vitest run <path> --maxWorkers=1\`) or a small node script — never modify files. REJECT if the code does not behave as the finding says, or the behavior is intended per the owner decisions in section 4 of the brief.
- Verdict: CONFIRMED (real, as stated), AMENDED (real, but the description, severity or location needs correcting — say how in \`reason\`), REJECTED (not a real problem — say exactly why). Do not default either way when uncertain: reason from the screen context and state what decided it.

(2) \`fix\` — only for findings that are not REJECTED: is the \`proposed\` change one the owner would accept? The owner's stated fear is overcorrection: generic or bland copy, lost judgment, verbosity, awkward literalism, childish language, removed sales terminology, inconsistent terms, and copy that no longer matches what the product does.
- Accurate: read the code that produces the text and the data behind it. The wording must claim only what the code does (for example, not "buyer activity" where the code measures when a record was last updated). A functional fix must be correct, minimal, and safe for stored data and callers.
- Judgment kept: it keeps the operator judgment, specificity and decisiveness of the current text.
- Plain without being awkward: a seller would say it out loud; it still fits where it sits (button, chip, heading, table cell, tooltip). A string passed through t() with class "label" must be 6 words or fewer (see src/lib/voice).
- Consistent: the same thing gets the same word across this area and matches how the default (v4) screens and COPY_STANDARD.md already name it — grep to check.
- Rules: it must not itself break COPY_STANDARD.md (including §26), the original rewrite documents, or the owner decisions in the brief §4; it must not rename identifiers, keys or routes or weaken a test. If the original working set gives an exact replacement for this string, the proposal should be that replacement unless it is inaccurate to current behavior or superseded by an owner decision (say which).
- Verdict: CONFIRMED (good as written), AMENDED (put the better final text or change in \`finalProposed\` and say why), REJECTED (no acceptable change exists, or making it would do damage — explain, and say what should happen instead). Use "N/A" when \`real\` is REJECTED.

Also:
- Check every disposition whose status is STILL MISSING, SUPERSEDED BY APPROVED PRODUCT EVOLUTION or NO LONGER APPLICABLE, plus a sample of at least 12 of the others (all of them if there are fewer): is the evidence real (open the file; grep the walkthrough text under ${S}/corpus/, ${S}/corpus-smb/, ${S}/corpus-ds/)? Is the status the right one of the five? Put problems in \`dispositionChallenges\`.
- With your remaining effort, find what the reviewer MISSED in this area: states not covered (empty, error, loading, validation, success, partial), the older screen versions (ds/ and components/), generators, prompts, fallbacks, accessible labels, exports, handoffs, and terminology used two ways. Report each as a full finding object (the shape in the brief §7; ids ${a.key.toUpperCase()}-M01, -M02, …) in \`missed\`. Only real problems, verified at file:line.

${IGNORE}
Machine note: other reviewers are working in this checkout at the same time and the machine is small. Do NOT start a browser, a dev server, a build, the whole test suite, or a copy of dist; at most one single-file vitest run at a time (--maxWorkers=1). Be economical: read a file once in full rather than through many small searches.

SAVE AS YOU GO: if ${out} already exists it is a partial result from an interrupted verifier — read it, keep its verdicts, and continue with the findings that have none. Write ${out} as valid JSON after your first five verdicts and rewrite it after every further five — this machine has been restarting without warning about once an hour, and a restart ends your session.

Shape of ${out}:
{ "area": "${a.key}",
  "verdicts": [ { "findingId": "…", "real": "CONFIRMED|AMENDED|REJECTED", "fix": "CONFIRMED|AMENDED|REJECTED|N/A", "reason": "…", "finalProposed": "(the final text or change when fix is AMENDED)", "checked": "file:line you actually opened" } ],
  "dispositionChallenges": [ { "recordId": "…", "issue": "…", "suggestedStatus": "…" } ],
  "missed": [ { …finding object… } ] }
Validate it and fix anything reported: node ${S}/validate-verify2.js ${out} ${audit}

Return: area, the output file path, whether validation passed, how many findings you judged real (CONFIRMED + AMENDED) and how many REJECTED, how many fixes you AMENDED or REJECTED, the number of missed findings you added, and a short note.`
}

// Reviewers inherit the session's model and effort unless args.model names another model.
const MODEL = (args && args.model) || null
async function run(prompt, opts) {
  return agent(prompt, MODEL ? { ...opts, model: MODEL } : opts)
}

const KEYS = (args && args.keys) || []
const VERIFY_ONLY = (args && args.verifyOnly) || []
const RUN = [...VERIFY_ONLY, ...KEYS].map(k => AREAS.find(a => a.key === k)).filter(Boolean)
log(`Areas, in priority order: ${RUN.map(a => a.key).join(', ')}. Each area is audited, then verified, before its lane moves to the next.`)

const out = []
async function lane(list) {
  for (const a of list) {
    const summary = VERIFY_ONLY.includes(a.key)
      ? { area: a.key, outFile: '', validated: true, findings: 1, dispositions: 0, notes: 'audit file already written by an earlier run' }
      : await run(auditPrompt(a), { label: `audit:${a.key}`, phase: 'Audit', schema: SUMMARY })
    let v = null
    if (summary) v = await run(verifyPrompt(a), { label: `verify:${a.key}`, phase: 'Verify', schema: VSUMMARY })
    else log(`audit did not finish for ${a.key} — its saved partial file (if any) is under ${S}/audit/; no verification run`)
    out.push({ area: a.key, audit: summary, verify: v })
  }
}
await parallel([
  () => lane(RUN.filter((_, i) => i % 2 === 0)),
  () => lane(RUN.filter((_, i) => i % 2 === 1)),
])

log(`${out.filter(r => r.audit && r.verify).length}/${RUN.length} areas audited and verified`)
return out.map(r => ({
  area: r.area,
  audit: r.audit ? { ok: r.audit.validated, findings: r.audit.findings, dispositions: r.audit.dispositions, sev3: r.audit.severity3 || 0, owner: (r.audit.ownerDecisions || '').slice(0, 300), notes: (r.audit.notes || '').slice(0, 700) } : null,
  verify: r.verify ? { ok: r.verify.validated, real: r.verify.real, rejected: r.verify.rejected, fixesChanged: r.verify.fixesChanged || 0, missed: r.verify.missed, notes: (r.verify.notes || '').slice(0, 300) } : null,
}))
